files.content:
* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 850px;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
}

.page-title {
  max-width: 780px;
  margin: 0 auto 50px;
  text-align: center;
}

.content {
  display: flex;
  flex-wrap: wrap;

  /* Удалите justify-content */

  max-width: 780px;
  margin: 0 50px;
}

.card {
  margin-right: 25px;
  margin-bottom: 25px;
  display: flex;
  align-items: center;
  width: 350px;
  border: 1px solid #fd24af;
  padding: 25px;
}

.card__img {
  width: 150px;
  margin-right: 5%;
}
